      <h3 class="section-title">Risks to the Outlook</h3>
      <div id="c_risks" class="chart-container"></div>
    </div>
    <div>
      <h3 class="section-title">Policy Actions for Sustained Growth</h3>
      <div id="c_policy" class="chart-container"></div>
    </div>
  </div>

  <div style="margin-top: 40px;">
    <h3 class="section-title">World Bank 2030 Strategic Priorities</h3>
    <div id="c_strategic" class="chart-container" style="background: transparent; border: none; padding: 0;"></div>
  </div>

  <div style="margin-top: 20px;">
    <h3 class="section-title">Key Research Themes</h3>
    <div id="c_research" class="chart-container"></div>
  </div>

</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
  const colors = '#004B87 #0072CE #008578 #FFB81C';

