  desc Increasing uncertainty threatens vulnerable economies
  lists
    - label Trade Tensions
      desc Escalation of tariffs and retaliatory measures disrupt supply chains
    - label Market Volatility
      desc Deterioration in sentiment tightens financing for EMDEs
    - label Inventory Correction
      desc Firms drawing down stocks, reducing near-term demand
    - label Climate Shocks
      desc Extreme weather threatens agricultural output and infrastructure
theme
  palette ${colors}
  base
    text
      font-family Helvetica Neue, Arial, sans-serif`);

  renderInfo('#c_policy', `infographic compare-binary-horizontal-simple-fold
data
  title Global vs Domestic Action
  compares
    - label Global Action
      children
        - label Trade
          desc Improve multilateral environment
        - label Finance
          desc Ease external constraints
        - label Climate
          desc Scale up risk mitigation
        - label Investment
          desc Catalyze private capital
        - label Jobs
          desc Support cross-border mobility
    - label Domestic Action
      children
        - label Trade
          desc Diversify partners & products
        - label Finance
          desc Strengthen macro frameworks
        - label Climate
          desc Invest in infrastructure
        - label Investment
          desc Remove business bottlenecks
        - label Jobs
          desc Enhance skills development
theme
  palette ${colors}`);

  renderInfo('#c_strategic', `infographic list-grid-candy-card-lite
data
  title 5 Flagship Targets
  lists
    - label 1.5B People
      desc Health Services Target
    - label 300M People
      desc Mission 300 (Electricity in Sub-Saharan Africa)
    - label 300M Farmers
      desc AgriConnect (Move up agricultural value chain)
    - label 80M Women
      desc Access to capital for women-led businesses
    - label 1B+ People
      desc Water Forward commitment (400M WBG commitment)
theme
  palette ${colors}`);

  renderInfo('#c_research', `infographic list-row-horizontal-icon-arrow
data
  title Recent Analytical Depth
  desc Insight underpinning policy recommendations
  lists
    - label Fiscal Policy
      desc Rebuilding fiscal space and challenges in small states
    - label Trade & Supply Chains
      desc High trade costs and COVID-19 impact on value chains
    - label Commodity Markets
      desc Price cycles and energy implications
    - label Financial Spillovers
      desc Rising U.S. interest rates and rapid debt buildup
    - label Pandemic Economics
      desc Impact on global income inequality
theme
  palette ${colors}`);
</script>
</body>
</html>
